package com.muxigame.city;
import java.util.*;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.neoforge.network.PacketDistributor;

/** Optional integration reads the archive's own validated NBT; approval never pastes a finished building. */
public final class CityArchiveBridge {
 public record Draft(UUID ticket,UUID city,long revision,long cityRevision,String name,String type,UUID owner,CityBounds bounds,Map<Long,String> blocks,Set<Long> air,Map<Long,String> blockData,long expires){}
 static final Map<UUID,Draft> drafts=new HashMap<>();
 static Path folder(ServerPlayer p){return p.server.getWorldPath(LevelResource.ROOT).resolve("building_archive");}
 static List<String> files(ServerPlayer p){try{Path root=folder(p);if(!Files.isDirectory(root))return List.of();try(var stream=Files.list(root)){return stream.filter(f->Files.isRegularFile(f,LinkOption.NOFOLLOW_LINKS)&&f.getFileName().toString().endsWith(".nbt")).map(f->f.getFileName().toString().replaceFirst("\\.nbt$","")).sorted().limit(256).toList();}}catch(Exception ex){return List.of();}}
 static CompoundTag read(ServerPlayer p,String file)throws Exception{CityEconomy.require(file.matches("[\\p{L}\\p{N}_-]{1,64}"),"建筑档案名称无效");Path path=folder(p).resolve(file+".nbt");CityEconomy.require(!Files.isSymbolicLink(path),"不读取链接档案");try{Class<?> api=Class.forName("com.muxigame.buildingarchive.ArchiveData");var nbt=(CompoundTag)api.getMethod("read",Path.class).invoke(null,path);api.getMethod("validate",CompoundTag.class).invoke(null,nbt);return nbt;}catch(java.lang.reflect.InvocationTargetException ex){throw new IllegalArgumentException(ex.getCause().getMessage());}catch(ClassNotFoundException ex){throw new IllegalArgumentException("请安装建筑档案模组后使用施工蓝图");}}
 static Draft decode(ServerPlayer p,CityData.City c,CompoundTag nbt,String name,String type,UUID owner,BlockPos origin,int turns,boolean mirror){CityEconomy.require(c.works.finalized,"先完成城市首次定稿");CityData.validName(name);CityEconomy.require(CityRegistry.TYPES.contains(type),"建筑用途无效");CityEconomy.require(!(type.equals("住宅")||type.equals("工坊"))||owner!=null&&c.residents.contains(owner),"私人住宅/工坊需要指定本城房主");var size=nbt.getList("size",Tag.TAG_INT);int sx=size.getInt(0),sy=size.getInt(1),sz=size.getInt(2);CityEconomy.require(turns>=0&&turns<4&&sx>0&&sy>0&&sz>0&&(long)sx*sy*sz<=32768,"蓝图尺寸或旋转无效");int dx=turns%2==0?sx:sz,dz=turns%2==0?sz:sx;var bounds=CityBounds.between(origin,origin.offset(dx-1,sy-1,dz-1));CityRegistry.inside(c,bounds);for(int i=0;i<bounds.volume();i++)CityEconomy.require(c.includes(bounds.at(i)),"蓝图覆盖城市排除区");for(var b:c.buildings.values())if(b.bounds().intersects(bounds))CityEconomy.require(CityHousing.house(c,b.id()).stage.equals("ABANDONED"),"蓝图与正在使用/施工的建筑重叠");
  var palette=nbt.getList("palette",Tag.TAG_COMPOUND);var lookup=p.serverLevel().registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.BLOCK);Map<Long,String> blocks=new LinkedHashMap<>(),metadata=new HashMap<>();Set<Long> air=new HashSet<>();for(int i=0;i<bounds.volume();i++)air.add(bounds.at(i).asLong());
  for(Tag raw:nbt.getList("blocks",Tag.TAG_COMPOUND)){var entry=(CompoundTag)raw;var at=entry.getList("pos",Tag.TAG_INT);int x=at.getInt(0),y=at.getInt(1),z=at.getInt(2);if(mirror)x=sx-1-x;int a=x,b=z,tx=sx,tz=sz;for(int n=0;n<turns;n++){int old=a;a=tz-1-b;b=old;int oldSize=tx;tx=tz;tz=oldSize;}var pos=origin.offset(a,y,b);BlockState state=NbtUtils.readBlockState(lookup,palette.getCompound(entry.getInt("state")));if(mirror)state=state.mirror(Mirror.FRONT_BACK);for(int n=0;n<turns;n++)state=state.rotate(Rotation.CLOCKWISE_90);if(state.isAir())continue;air.remove(pos.asLong());blocks.put(pos.asLong(),CityMaintenance.encode(state));var source=entry.getCompound("nbt");var safe=new CompoundTag();for(String key:List.of("id","RuralWorkOffset","front_text","back_text","is_waxed","color","Patterns","CustomName"))if(source.contains(key))safe.put(key,source.get(key).copy());if(safe.contains("RuralWorkOffset")){int[] offset=safe.getIntArray("RuralWorkOffset");CityEconomy.require(offset.length==3,"储藏箱关联偏移格式无效");int ox=mirror?-offset[0]:offset[0],oz=offset[2];for(int n=0;n<turns;n++){int old=ox;ox=-oz;oz=old;}safe.putIntArray("RuralWorkOffset",new int[]{ox,offset[1],oz});}if(!safe.isEmpty())metadata.put(pos.asLong(),safe.toString());}
  CityEconomy.require(!blocks.isEmpty(),"蓝图没有可施工方块");return new Draft(UUID.randomUUID(),c.id,c.works.revision,c.revision,name,type,owner,bounds,blocks,air,metadata,p.server.overworld().getGameTime()+1200);
 }
 static Draft preview(ServerPlayer p,CityData.City c,String file,String name,String type,UUID owner,BlockPos origin,int turns,boolean mirror)throws Exception{var draft=decode(p,c,read(p,file),name,type,owner,origin,turns,mirror);drafts.put(p.getUUID(),draft);var t=new CompoundTag();t.putBoolean("WorksPreview",true);t.putLong("Min",draft.bounds.min().asLong());t.putLong("Max",draft.bounds.max().asLong());t.putString("Dimension",c.dimension);var samples=new ListTag();draft.blocks.keySet().stream().limit(2048).forEach(v->samples.add(LongTag.valueOf(v)));t.put("Samples",samples);PacketDistributor.sendToPlayer(p,new CityNetwork.Snapshot(t));return draft;}
 static UUID approve(ServerPlayer p,CityData.City c,UUID ticket){var draft=drafts.get(p.getUUID());CityEconomy.require(draft!=null&&draft.ticket.equals(ticket)&&draft.city.equals(c.id)&&draft.revision==c.works.revision&&draft.cityRevision==c.revision&&p.server.overworld().getGameTime()<=draft.expires,"预览已失效，请重新预览后下达");CityRegistry.inside(c,draft.bounds);var actual=new HashMap<Long,BlockState>();for(int i=0;i<draft.bounds.volume();i++){var pos=draft.bounds.at(i);CityEconomy.require(c.includes(pos),"蓝图区域已被排除，请重新预览");actual.put(pos.asLong(),CityWorks.dataAt(p.server,c,pos.asLong()));}for(var b:new ArrayList<>(c.buildings.values()))if(b.bounds().intersects(draft.bounds)){var old=CityHousing.house(c,b.id());CityEconomy.require(old.stage.equals("ABANDONED"),"建筑占地已改变，请重新预览");for(var block:old.baseline.entrySet())if(!old.damaged.contains(block.getKey())&&!Objects.equals(draft.blocks.get(block.getKey()),block.getValue())){c.works.ruins.put(block.getKey(),block.getValue());if(old.owner!=null)c.works.ruinOwners.put(block.getKey(),old.owner);}c.housing.houses.remove(b.id());c.buildings.remove(b.id());}
  UUID id=UUID.randomUUID();c.buildings.put(id,new CityRegistry.Building(id,draft.name,draft.type,draft.bounds));var h=CityHousing.house(c,id);h.owner=draft.owner;h.configured=true;h.extra=true;h.stage="PLANNED";h.baseline.putAll(draft.blocks);h.clears.addAll(draft.air);h.blockData.putAll(draft.blockData);var level=p.serverLevel();for(var block:h.baseline.entrySet()){var pos=BlockPos.of(block.getKey());BlockState current=actual.get(block.getKey());if(!CityBlockRules.same(current,CityMaintenance.decode(block.getValue())))h.damaged.add(block.getKey());}for(long packed:h.clears){var pos=BlockPos.of(packed);var existing=actual.get(packed);if(!existing.isAir()&&!CityBlockRules.ignored(existing)){h.pendingClear.add(packed);c.works.illegal.put(packed,CityMaintenance.encode(existing));}}for(long packed:h.baseline.keySet()){if(!h.damaged.contains(packed)){c.works.ruins.remove(packed);c.works.ruinOwners.remove(packed);}}CityWorks.completed(h);c.works.revision++;CityData.get(p.server).changed(c);drafts.remove(p.getUUID());return id;
 }
 static void cancel(CityData.City c,UUID id){var h=CityHousing.house(c,id);CityEconomy.require(h.stage.equals("PLANNED"),"只能取消尚未竣工的蓝图");h.stage="ABANDONED";h.production=false;h.status="烂尾：空闲工匠最后拆除";c.works.revision++;}
}
